window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a742c96dcf9ea4ff"]={"versions": [{"id": "FIG-a742c96dcf9ea4ff", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-artiges Sequenzdiagramm im Kontext des AUTOSAR CAN Transport Layers (<code>CanTp</code>). Es illustriert den grundlegenden Kommunikationsablauf für unsegmentierte Datentransfers (Single Frame / Single Part Message) zwischen zwei Kommunikationspartnern über ein CAN-Netzwerk.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Sender</strong>: Sendende Instanz bzw. Transportprotokoll-Endpunkt (<code>CanTp</code>-Sender).\n</li><li><strong>Receiver</strong>: Empfangende Instanz bzw. Transportprotokoll-Endpunkt (<code>CanTp</code>-Empfänger).\n</li><li><strong>Single frame</strong>: Unsegmentierte Protokolldateneinheit (N-PDU bzw. CAN-Frame vom Typ Single Frame / SF), die direkt vom Sender zum Receiver übertragen wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Sender initiiert die Übertragung einer Nachricht, deren Länge in eine einzelne CAN-PDU passt (N-PDU Nutzlast ≤ 7 Bytes bei klassischem CAN mit Standard-Addressing bzw. ≤ 6 Bytes bei Extended/Mixed-Addressing).\n</li><li>Der Sender überträgt die Nachricht direkt in Form eines einzelnen Frames (<code>Single frame</code>) asynchron über den Bus an den Receiver.\n</li><li>Die Übertragung ist mit dem Eintreffen des <code>Single frame</code> auf der Empfängerseite abgeschlossen; es erfolgt auf Transportprotokollebene keine Flusskontrolle (<code>Flow Control</code>) und keine explizite Bestätigung.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht das Basisszenario der CAN-TP-Spezifikation (ISO 15765-2 / AUTOSAR SWS CanTp) für Botschaften ohne Segmentierung. Entwickler müssen sicherstellen, dass bei Datenlängen innerhalb der SF-Grenzen direkt eine SF-N-PDU assembliert und versendet wird, ohne Segmentierungs- und Reassembly-Zustandsmaschinen oder Flusskontroll-Timer zu aktivieren.</p>"}, {"id": "FIG-75c8839af2507933", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-artiges Sequenzdiagramm im Kontext des AUTOSAR CAN Transport Layers (<code>CanTp</code>). Es illustriert den grundlegenden Kommunikationsablauf für unsegmentierte Datentransfers (Single Frame / Single Part Message) zwischen zwei Kommunikationspartnern über ein CAN-Netzwerk.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Sender</strong>: Sendende Instanz bzw. Transportprotokoll-Endpunkt (<code>CanTp</code>-Sender).\n</li><li><strong>Receiver</strong>: Empfangende Instanz bzw. Transportprotokoll-Endpunkt (<code>CanTp</code>-Empfänger).\n</li><li><strong>Single frame</strong>: Unsegmentierte Protokolldateneinheit (N-PDU bzw. CAN-Frame vom Typ Single Frame / SF), die direkt vom Sender zum Receiver übertragen wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Sender initiiert die Übertragung einer Nachricht, deren Länge in eine einzelne CAN-PDU passt (N-PDU Nutzlast ≤ 7 Bytes bei klassischem CAN mit Standard-Addressing bzw. ≤ 6 Bytes bei Extended/Mixed-Addressing).\n</li><li>Der Sender überträgt die Nachricht direkt in Form eines einzelnen Frames (<code>Single frame</code>) asynchron über den Bus an den Receiver.\n</li><li>Die Übertragung ist mit dem Eintreffen des <code>Single frame</code> auf der Empfängerseite abgeschlossen; es erfolgt auf Transportprotokollebene keine Flusskontrolle (<code>Flow Control</code>) und keine explizite Bestätigung.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht das Basisszenario der CAN-TP-Spezifikation (ISO 15765-2 / AUTOSAR SWS CanTp) für Botschaften ohne Segmentierung. Entwickler müssen sicherstellen, dass bei Datenlängen innerhalb der SF-Grenzen direkt eine SF-N-PDU assembliert und versendet wird, ohne Segmentierungs- und Reassembly-Zustandsmaschinen oder Flusskontroll-Timer zu aktivieren.</p>"}, {"id": "FIG-b3a9528ef982c167", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-artiges Sequenzdiagramm im Kontext des AUTOSAR CAN Transport Layers (<code>CanTp</code>). Es illustriert den grundlegenden Kommunikationsablauf für unsegmentierte Datentransfers (Single Frame / Single Part Message) zwischen zwei Kommunikationspartnern über ein CAN-Netzwerk.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Sender</strong>: Sendende Instanz bzw. Transportprotokoll-Endpunkt (<code>CanTp</code>-Sender).\n</li><li><strong>Receiver</strong>: Empfangende Instanz bzw. Transportprotokoll-Endpunkt (<code>CanTp</code>-Empfänger).\n</li><li><strong>Single frame</strong>: Unsegmentierte Protokolldateneinheit (N-PDU bzw. CAN-Frame vom Typ Single Frame / SF), die direkt vom Sender zum Receiver übertragen wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Sender initiiert die Übertragung einer Nachricht, deren Länge in eine einzelne CAN-PDU passt (N-PDU Nutzlast ≤ 7 Bytes bei klassischem CAN mit Standard-Addressing bzw. ≤ 6 Bytes bei Extended/Mixed-Addressing).\n</li><li>Der Sender überträgt die Nachricht direkt in Form eines einzelnen Frames (<code>Single frame</code>) asynchron über den Bus an den Receiver.\n</li><li>Die Übertragung ist mit dem Eintreffen des <code>Single frame</code> auf der Empfängerseite abgeschlossen; es erfolgt auf Transportprotokollebene keine Flusskontrolle (<code>Flow Control</code>) und keine explizite Bestätigung.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht das Basisszenario der CAN-TP-Spezifikation (ISO 15765-2 / AUTOSAR SWS CanTp) für Botschaften ohne Segmentierung. Entwickler müssen sicherstellen, dass bei Datenlängen innerhalb der SF-Grenzen direkt eine SF-N-PDU assembliert und versendet wird, ohne Segmentierungs- und Reassembly-Zustandsmaschinen oder Flusskontroll-Timer zu aktivieren.</p>"}], "trans": [{"from": "FIG-a742c96dcf9ea4ff", "to": "FIG-75c8839af2507933", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-75c8839af2507933", "to": "FIG-b3a9528ef982c167", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
